target = '.....(((.(..(.(((((.((((.((...)))).))))((((((...)).))))..(((...)))...))).)..).)))....................'
print(f'Length: {len(target)}')
# Parse pairs
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j
for i in sorted(pairs):
    if i < pairs[i]:
        print(f'({i},{pairs[i]})')
"
